import{_ as l,l as s,o as e,c as i,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"距离向量","description":"","frontmatter":{"title":"距离向量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distance-vector.md","filePath":"cs/distance-vector.md","lastUpdated":1789023840000}'),h={name:"cs/distance-vector.md"};function E(B,a,_,m,A,P){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="距离向量" tabindex="-1">距离向量 <a class="header-anchor" href="#距离向量" aria-label="Permalink to &quot;距离向量&quot;">​</a></h1><div class="epigraph"><p>每个路由器只告诉邻居：我到各前缀的距离；邻居取最小，像分布式的松弛。</p><footer>—— 据 Ford, Fulkerson 与 Bellman 的最短路松弛；RFC 2453 RIP Version 2 整理</footer></div><p><a href="/cs/ipv6-ndp">上一课</a>假定转发表已在。<a href="/cs/lpm">LPM</a> 只查找不填表。缺口是控制平面的一种：邻居交换「到某前缀多远」，本地做松弛。图课的 <a href="/cs/bellman-ford">Bellman-Ford</a> 已给出边权松弛；本课把它放到路由器上，并点出无穷计数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态配下一跳不能跟故障。距离向量：周期性或触发地，把向量 \\((前缀, 距离)\\) 发给邻居。收到后，经该邻居的距离 = 通告距离 + 链路代价，比现有更好则更新。缺口不是 ICMP，而是这套分布式 BF。RIP 把无穷定为 16，跳数当代价，只适合小域。</p><p>本课不把 RIP 认证头写完。</p><p><span class="marginnote">无穷计数：链路断了，A 与 B 互相以为对方仍通，距离加到无穷。毒性逆转、水平分割是补丁，不是证明消失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化：直连前缀距离 0。通告整个向量（或增量）。失效：超时未刷新则置无穷并通告。与<a href="/cs/spanning-tree">生成树</a>不同：DV 在三层，键是 IP 前缀，允许任意拓扑上的多路径候选，转发仍只装一条或 ECMP。</p>',9)),(e(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E9%82%BB%E5%B1%85%E9%80%9A%E5%91%8A%E5%90%91%E9%87%8F%22%5D%20--%3E%20RELAX%5B%22%E7%BB%8F%E8%AF%A5%E9%82%BB%E5%B1%85%E6%9D%BE%E5%BC%9B%22%5D%0A%20%20RELAX%20--%3E%20TAB%5B%22%E6%9B%B4%E6%96%B0%20LPM%20%E8%A1%A8%22%5D%0A%20%20RELAX%20--%3E%20LOOP%5B%22%E5%9D%8F%E6%B6%88%E6%81%AF%E6%85%A2%3A%20%E6%97%A0%E7%A9%B7%E8%AE%A1%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DV 实现简单，内存只存向量，符合早期线路贵的环境。坏消息慢，是因为没有全局拓扑：断边之后仍可能引用彼此的旧好消息。端到端：路由震荡期间 IP 仍尽力转发，可能环到 TTL 尽，于是 <a href="/cs/icmp">ICMP 超时</a>出现。传输层看见丢包。</p><p>与进程调度无关：这是路由器进程（或内核协议）之间的消息，可用后课 UDP（RIP 正是如此）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 EIGRP 的 DUAL 写完，不引入路径向量——那是 BGP 用 AS 路径防环。也不把负权当互联网代价：链路代价为正。全局拓扑与更快收敛是下一课链路状态。</p><p>度量若用带宽或延迟，必须保证正且无震荡；RIP 用跳数正是为了简单。触发更新比定期全表更快送出坏消息。</p><p>不等间隔的定时器抖动，用来避免同步通告造成的周期性拥塞。</p><p>后课默认：邻居向量可填表，但环与慢收敛是代价。通告整图、本地跑最短路，下一课链路状态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>距离向量是分布式 Bellman-Ford，填 LPM。</li><li>无穷计数；水平分割只是缓解。</li><li>链路状态用整图对照，下一课。</li><li>出处：Bellman-Ford；RFC 2453；Kurose and Ross。</li></ul>',10))])}const T=l(h,[["render",E]]);export{u as __pageData,T as default};
